base_files.pricing.py:
def compute_total(items, tax):
    subtotal = sum(i["price"] * i["qty"] for i in items)
    return round(subtotal * (1 + tax), 2)

base_files.cart.py:
from pricing import compute_total


def checkout(items):
    return compute_total(items, 0.2)

